55474437bf15d51a:
#definition([उदाहरण: शर्तों पर निर्भर सैंपलिंग सीमा], [
  निश्चित त्रुटिपूर्ण अनुपात ⟦0⟧ और ⟦1⟧ स्वतंत्र ओपनिंग्स के साथ प्रत्येक ख़राब स्थान के छूटने की संभावना ⟦2⟧ है। 32 ओपनिंग्स पर यह लगभग 0.034 है। इस आधार में सैंपल चुनने से पूर्व कमिटमेंट स्थिर माना गया है। यदि प्रूवर कई रूट्स खोज सकता है, यह चुन सकता है कि कौन-सा कमिटमेंट दिखाना है, या विफलताओं को सहसंबद्ध कर सकता है, तो यह गणना उस रणनीति को शामिल नहीं करती।
])

e51753f477a22a66:
#objectives([
  समझाएँ कि जब जारीकर्ता (issuer) और सत्यापनकर्ता (verifier) एक ही ट्रस्ट डोमेन में हों, तो कीड स्यूडोरैंडम फ़ंक्शन (keyed PRF) ही सही प्रिमिटिव क्यों है। 128-बिट टैग की जालसाजी सीमा (forgery bound) बताएँ, स्टेटलेस चैलेंज रिकॉर्ड और स्पेंट-सेट बाउंड समझाएँ, तथा की-शेड्यूल का विश्लेषण करें।
])

045072c80151f3ea:
#callout([लेम्मा 3: जालसाजी सीमा (Forgery Bound)], [
  BLAKE3 के कीड मोड को PRF मानने और 16-बाइट टैग रखने पर, ⟦0⟧ सत्यापन क्वेरीज़ करने वाला हमलावर अधिकतम ⟦1⟧ प्रायिकता से ही किसी वैध टोकन की जालसाजी कर सकता है। प्रति सेकंड दस लाख क्वेरीज़ की दर पर भी यह ⟦2⟧ प्रति सेकंड है।
])

3d3ab8947b56bf17:
#callout([लेम्मा 4: स्टेट केवल चुकाए गए कार्य से बढ़ती है], [
  डेमन द्वारा याद रखे गए चैलेंज टैग्स का सेट ⟦0⟧ मान लें। किसी टैग का वैध प्रूफ़ स्वीकार होने के बाद ही वह ⟦1⟧ में जुड़ता है, और चैलेंज TTL समाप्त होने पर हट जाता है। अतः ⟦2⟧, जहाँ ⟦3⟧ उस अंतराल में स्वीकार किए गए विशिष्ट समाधानों की अधिकतम दर है। मुफ़्त चैलेंज प्राप्त करने पर कोई टैग मेमोरी में आवंटित नहीं होता। कार्यान्वयन की क्षमता भी निश्चित है; पूर्ण होने पर वह वैध समाधान अस्वीकार कर सकता है। यह एक स्टेट बाउंड है, किसी हमलावर की संगणना रणनीति का निचला बाउंड नहीं।
])

364afbb0e7ddec0d:
#exercise([3.3], [
  टोकन पेलोड में वर्क लेवल, ⟦0⟧, ⟦1⟧, ⟦2⟧ और ⟦3⟧ शामिल हैं। समझाएँ कि इनमें से प्रत्येक फ़ील्ड हटाने पर किस सुरक्षा पहलू से समझौता होता है। टैग में इन पाँचों को शामिल करना क्यों अनिवार्य है?
])

